// Builds paste-ready SQL for the Supabase SQL Editor from supabase/migrations.
// Each bundle runs in one transaction and records every migration in
// private.applied_migrations, refusing to apply one twice.
import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
import { root } from './migrated-db.mjs';

const migrationsDir = join(root, 'supabase', 'migrations');
export const setupDir = join(root, 'supabase', 'setup');

export function bundleFileName(since) {
  return since ? `update_after_${since}.sql` : 'full_setup.sql';
}

export function buildBundle({ since = null } = {}) {
  const files = readdirSync(migrationsDir)
    .filter((f) => f.endsWith('.sql'))
    .sort()
    .filter((f) => !since || f.split('_')[0] > since);

  const parts = [
    `-- BrandChilly PMS: ${since ? `update after ${since}` : 'full setup for a new Supabase project'}`,
    `-- Generated by scripts/build-sql-bundle.mjs. Do not edit; change supabase/migrations instead.`,
    `-- Paste into Supabase > SQL Editor and click Run.`,
    `-- Contains ${files.length} migration(s): ${files.map((f) => f.split('_')[0]).join(', ')}`,
    `-- Runs in one transaction: if anything fails, nothing is applied.`,
    '',
    'begin;',
    '',
    'create schema if not exists private;',
    `create table if not exists private.applied_migrations (
  version text primary key,
  name text not null,
  applied_at timestamptz not null default now()
);`,
    '',
  ];

  for (const file of files) {
    const version = file.split('_')[0];
    const sql = readFileSync(join(migrationsDir, file), 'utf8').trimEnd();
    parts.push(
      `-- ===========================================================================`,
      `-- ${file}`,
      `-- ===========================================================================`,
      `do $guard$ begin
  if exists (select 1 from private.applied_migrations where version = '${version}') then
    raise exception 'Migration ${version} is already applied to this project. Use an update file instead.';
  end if;
end $guard$;`,
      '',
      sql,
      '',
      `insert into private.applied_migrations (version, name) values ('${version}', '${file}');`,
      ''
    );
  }

  parts.push('commit;', '');
  return { sql: parts.join('\n'), files };
}
